#!/usr/bin/env bash
# crucible-vault user installer: build + install `cv` and `cvault-editor`, close the running
# editor (gracefully), stop the daemon, apply pending migrations, restart, relaunch the editor.
#
# Re-runnable: builds are incremental, a restart is harmless, and each migration in
# $CV_MIGRATIONS_DIR (default deploy/migrations/local) is applied once — its applied phases are recorded in
# ${XDG_STATE_HOME:-~/.local/state}/crucible-vault/install.applied and skipped afterwards.
# Contract for migrations: deploy/migrations/README.md.
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'install.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'install.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -euo pipefail

REPO=$(cd "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")" && pwd)
UNIT=crucible-vault.service
STATE_DIR=${XDG_STATE_HOME:-$HOME/.local/state}/crucible-vault
APPLIED=$STATE_DIR/install.applied
MIGRATIONS=${CV_MIGRATIONS_DIR:-$REPO/deploy/migrations/local}
# Shared migration helpers: exported so a migration in any CV_MIGRATIONS_DIR sources $CV_MIGRATIONS_LIB/anchor.sh.
export CV_MIGRATIONS_LIB=$REPO/deploy/migrations/lib
export REPO
# Private per-install settings (plan public-release WP-2): an optional KEY=value file, e.g.
# `CV_VAULT=/path/to/vault`, read before anything derives from the vault. An exported CV_VAULT wins.
LOCAL_ENV=$REPO/deploy/migrations/local/install.env
if [[ -z ${CV_VAULT:-} && -f $LOCAL_ENV ]]; then
  CV_VAULT=$(sed -n 's/^[[:space:]]*CV_VAULT=//p' "$LOCAL_ENV" | tail -n 1)
  CV_VAULT=${CV_VAULT%\"}; CV_VAULT=${CV_VAULT#\"}
  if [[ $CV_VAULT == \~/* ]]; then CV_VAULT=$HOME/${CV_VAULT:2}; fi
fi
export VAULT=${CV_VAULT:-$HOME/vault}
# The daemon, migrations and `cv` calls below resolve this same vault.
export CV_VAULT=$VAULT
export CONFIG_DIR=${CV_CONFIG_DIR:-$VAULT/_custom/crucible-vault}
export STATE_DB=${CV_STATE_DB:-$STATE_DIR/state.db}

skip_build=0
touch_editor=1
list_only=0

usage() {
  cat <<'EOF'
usage: ./install.sh [--list] [--skip-build] [--no-editor]

  --list        show migrations and whether each phase is applied, then exit
  --skip-build  do not run `cargo install` (restart + migrations only)
  --no-editor   leave cvault-editor alone (not closed, not relaunched)

environment:
  CV_MIGRATIONS_DIR  directory of NNNN-<slug>.sh data migrations to apply
                     (default: <repo>/deploy/migrations/local; may be any directory)
EOF
}

. "$REPO/scripts/lib/build-id.sh"
. "$REPO/scripts/lib/cde.sh"
. "$REPO/scripts/lib/backup.sh"
case " $* " in *" --help "* | *" -h "*) usage; exit 0 ;; esac
build_flags "${BASH_SOURCE[0]}" "$@"

for a in "$@"; do
  case $a in
    --list) list_only=1 ;;
    --skip-build) skip_build=1 ;;
    --no-editor) touch_editor=0 ;;
    -h | --help) usage; exit 0 ;;
    *) usage >&2; exit 2 ;;
  esac
done

say() { printf '\033[1m==> %s\033[0m\n' "$*"; }
warn() { printf '\033[33mwarning:\033[0m %s\n' "$*" >&2; }
die() { printf '\033[31merror:\033[0m %s\n' "$*" >&2; exit 1; }

mkdir -p "$STATE_DIR"
touch "$APPLIED"
exec 9>"$STATE_DIR/install.lock"
flock -n 9 || die "another install.sh is running"

# --- daemon vault ---------------------------------------------------------------------------

# The unit names no vault, so install.sh pins the daemon to the vault it resolved above (plan
# public-release WP-2): crucible-vault.service.d/vault.conf sets CV_VAULT and makes the vault
# writable (ProtectHome=read-only otherwise). Rewritten only when its content differs.
VAULT_DROPIN=${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user/$UNIT.d/vault.conf
[[ $VAULT != *[[:space:]]* ]] \
  || die "vault path '$VAULT' contains whitespace; systemd splits ReadWritePaths= on whitespace"
write_vault_dropin() {
  local want
  want=$(printf '%s\n' \
    '# generated by install.sh from the vault it resolved (CV_VAULT, deploy/migrations/local/install.env, else ~/vault)' \
    '[Service]' \
    "Environment=CV_VAULT=$VAULT" \
    "ReadWritePaths=-$VAULT")
  if [[ -f $VAULT_DROPIN ]] && [[ $(cat -- "$VAULT_DROPIN") == "$want" ]]; then
    return 0
  fi
  if [[ -e $VAULT_DROPIN ]]; then BACKUP_DIR=$STATE_DIR/install-backups/vault-dropin backup "$VAULT_DROPIN"; fi
  mkdir -p "$(dirname "$VAULT_DROPIN")"
  printf '%s\n' "$want" >"$VAULT_DROPIN"
  echo "    daemon vault: wrote $VAULT_DROPIN ($VAULT)"
}

# --- migrations ----------------------------------------------------------------------------

migration_files() {
  [[ -d $MIGRATIONS ]] || return 0
  find "$MIGRATIONS" -maxdepth 1 -type f -name '[0-9][0-9][0-9][0-9]-*.sh' | sort
}

is_applied() { grep -qxF -- "$1" <(cut -d' ' -f1 "$APPLIED"); }

# Prints the phases (`stopped`, `running`) a migration file defines.
phases_of() {
  ( # shellcheck source=/dev/null
    source "$1"
    for p in stopped running; do
      declare -F "migrate_$p" >/dev/null && echo "$p"
    done )
}

# `backup <file>` (scripts/lib/backup.sh, sourced above) copies a file into this run's backup dir; migrations call it before editing.
export -f backup

run_phase() {
  local phase=$1 f id key ran=0
  while IFS= read -r f; do
    id=$(basename "$f" .sh)
    # Captured, not piped into `grep -q` (pipefail + an early grep exit = a false miss).
    [[ " $(phases_of "$f" | tr '\n' ' ') " == *" $phase "* ]] || continue
    key="$id:$phase"
    is_applied "$key" && continue
    say "migration $key"
    export BACKUP_DIR=$STATE_DIR/install-backups/$id
    if ! ( set -euo pipefail
           # shellcheck source=/dev/null
           source "$f"
           "migrate_$phase" ); then
      die "migration $key failed — nothing recorded; fix the cause and re-run ./install.sh"
    fi
    printf '%s %s %s\n' "$key" "$(date -Is)" "$(git -C "$REPO" rev-parse --short HEAD 2>/dev/null || echo -)" >>"$APPLIED"
    ran=1
  done < <(migration_files)
  [[ $ran = 1 ]] || echo "    (no pending $phase-phase migrations)"
}

if [[ $list_only = 1 ]]; then
  while IFS= read -r f; do
    id=$(basename "$f" .sh)
    for p in $(phases_of "$f"); do
      if is_applied "$id:$p"; then echo "applied  $id:$p"; else echo "pending  $id:$p"; fi
    done
  done < <(migration_files)
  exit 0
fi

# --- build ---------------------------------------------------------------------------------

if [[ $skip_build = 0 ]]; then
  command -v cargo >/dev/null || die "cargo not found on PATH"
  if [[ -n $(git -C "$REPO" status --porcelain -- crates Cargo.toml Cargo.lock 2>/dev/null) ]]; then
    warn "uncommitted changes under crates/ are being built"
  fi
  say "building $(git -C "$REPO" log -1 --format='%h %s' 2>/dev/null || echo "$REPO")"
  cargo install --locked --path "$REPO/crates/cv"
  cargo install --locked --path "$REPO/crates/editor"
fi

# --- desktop entry -------------------------------------------------------------------------

# Lists the editor in XDG launchers (CDE's Super+Return, menus). Exec is the absolute installed
# path: a launcher's PATH need not contain the cargo bin dir. Rewritten on every run.
editor_bin=${CARGO_INSTALL_ROOT:-${CARGO_HOME:-$HOME/.cargo}}/bin/cvault-editor
apps_dir=${XDG_DATA_HOME:-$HOME/.local/share}/applications
if [[ -x $editor_bin ]]; then
  mkdir -p "$apps_dir"
  cat >"$apps_dir/cvault-editor.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=cvault-editor
Comment=Crucible vault editor
Exec=$editor_bin
Terminal=false
Categories=Office;TextEditor;
EOF
  echo "    desktop entry: $apps_dir/cvault-editor.desktop"
else
  warn "no cvault-editor at $editor_bin; desktop entry not written"
fi

# --- close the editor ----------------------------------------------------------------------

editor_was_running=0
if [[ $touch_editor = 1 ]] && pgrep -x cvault-editor >/dev/null; then
  editor_was_running=1
  say "closing cvault-editor"
  # A window close request is the editor's Quit: dirty buffers flush first, and the
  # unsaved-edits dialog appears if a save fails. Never killed.
  # Under CDE: ask the compositor to close the window by pid (same graceful close request).
  closed_via_cde=0
  if cde_sock=$(cde_socket); then
    for pid in $(pgrep -x cvault-editor); do
      if reply=$(cde_msg "$cde_sock" close-pid "$pid"); then
        echo "    asked CDE to close cvault-editor (pid $pid)"
        closed_via_cde=1
      else
        echo "    CDE close-pid failed for pid $pid: $reply"
      fi
    done
  fi
  if [[ $closed_via_cde = 1 ]]; then
    :
  elif [[ -n ${DISPLAY:-} ]] && command -v wmctrl >/dev/null; then
    for pid in $(pgrep -x cvault-editor); do
      wmctrl -lp | awk -v p="$pid" '$3 == p { print $1 }' | while read -r w; do
        wmctrl -i -c "$w" || true
      done
    done
  else
    echo "    please quit cvault-editor yourself (no DISPLAY/wmctrl to ask it)"
  fi
  waited=0
  while pgrep -x cvault-editor >/dev/null; do
    if (( waited % 15 == 0 && waited > 0 )); then
      echo "    still waiting for cvault-editor to quit — answer its dialog if one is open (Ctrl-C aborts; nothing has been changed yet)"
    fi
    sleep 1
    waited=$((waited + 1))
  done
fi

# --- daemon stopped: migrations ------------------------------------------------------------

say "stopping $UNIT"
systemctl --user stop "$UNIT"
write_vault_dropin
systemctl --user daemon-reload
run_phase stopped

# --- daemon running ------------------------------------------------------------------------

say "starting $UNIT"
systemctl --user start "$UNIT"
for _ in $(seq 1 60); do
  cv status 2>/dev/null | grep -qx 'daemon: running' && break
  sleep 1
done
cv status | grep -qx 'daemon: running' || die "daemon did not come up — journalctl --user -u $UNIT"
run_phase running

status=$(cv status)
echo "$status"
config_ok=1
if ! grep -qx 'config errors: none' <<<"$status"; then
  config_ok=0
  warn "config errors reported above — migration backups are under $STATE_DIR/install-backups/"
fi

# --- relaunch the editor -------------------------------------------------------------------

if [[ $editor_was_running = 1 ]]; then
  say "relaunching cvault-editor"
  # 9>&-: the editor must not inherit the install.lock fd, or it holds the flock for its whole
  # lifetime and every later install.sh fails with "another install.sh is running".
  # Under CDE the compositor spawns it into the focused pane (absolute path: its PATH may lack
  # the cargo bin dir); otherwise, or if that fails, a detached session.
  reply=
  if cde_sock=$(cde_socket) && reply=$(cde_msg "$cde_sock" run "$editor_bin"); then
    echo "    asked CDE to run cvault-editor"
  else
    [[ -z ${reply:-} ]] || echo "    CDE run failed: $reply"
    setsid -f cvault-editor 9>&- </dev/null >/dev/null 2>&1
  fi
fi

[[ $config_ok = 1 ]] || exit 1
say "done"
